*{box-sizing:border-box}body{margin:0;background:#101611;color:var(--paper);font-family:var(--sans);min-height:100vh}.app-shell{max-width:1440px;margin:auto;padding:0 56px;min-height:100vh;display:flex;flex-direction:column}.topbar{height:78px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;position:relative;z-index:2}.brand{display:flex;align-items:center;gap:11px;color:var(--paper);font-weight:700;font-size:13px;letter-spacing:.16em;text-decoration:none}.brand-mark{color:var(--gold);font-size:23px}.brand-muted{color:#8e988d;font-weight:500}.topbar-center,.eyebrow,.footer,.stat-label,.inventory-title{font-family:var(--mono);letter-spacing:.12em;font-size:10px;color:#aab1a1}.topbar-center{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px}.campaign-dot,.live-dot{height:6px;width:6px;border-radius:50%;background:#c9a65e;box-shadow:0 0 11px #d4ae5e}.quiet-button{background:none;border:0;color:#aeb6a8;font:500 12px var(--sans);cursor:pointer;padding:9px}.quiet-button:hover{color:var(--gold2)}.quiet-button:first-letter{font-size:18px;margin-right:4px}.layout{flex:1;display:grid;grid-template-columns:260px minmax(0,1fr);gap:30px;padding:31px 0 25px;min-height:0}.sidebar{display:flex;flex-direction:column;gap:15px}.profile-card,.journal-card{background:#19231b;border:1px solid rgba(241,235,213,.09);border-radius:8px;padding:20px}.profile-top,.journal-heading{display:flex;align-items:center;justify-content:space-between}.level-pill{font:10px var(--mono);color:var(--gold);border:1px solid rgba(229,185,103,.28);padding:5px 7px;border-radius:3px}.avatar-wrap{width:80px;height:80px;margin:20px auto 10px;position:relative}.avatar{height:80px;width:80px;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle at 38% 30%,#53654e,#26362b 65%,#1b281f);border:1px solid rgba(229,185,103,.4);font-size:30px;color:var(--gold2);font-family:var(--serif)}.avatar-spark{position:absolute;right:-2px;bottom:2px;color:var(--gold);font-size:17px}.profile-card h2{text-align:center;font:600 22px var(--serif);margin:0;color:#f5efdc}.hero-role{text-align:center;color:#a6afa2;font-size:12px;margin:5px 0 21px}.stat-block{margin:13px 0}.stat-label{display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:.1em;color:#adb5a7;margin-bottom:8px}.stat-label>span:last-child{font-size:10px;color:#e8e6d9}.stat-icon{font-style:normal;margin-right:5px}.heart{color:#dc826e}.coin{color:var(--gold)}.meter{height:5px;background:#303b31;border-radius:5px;overflow:hidden}.meter-fill{height:100%;width:0;transition:width .35s ease;border-radius:5px}.health-fill{background:linear-gradient(90deg,#c4675c,#e79576)}.renown-fill{background:linear-gradient(90deg,#b38a4d,#e7bd72)}.inventory{border-top:1px solid var(--line);margin-top:19px;padding-top:15px}.inventory-title{display:flex;justify-content:space-between;font-size:9px}.inventory-title span{color:#727e70}.inventory-items{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}.item-chip{font-size:10px;color:#d9cfb2;background:#28342a;border:1px solid #3a4938;border-radius:3px;padding:5px 7px}.empty-pack{font-size:11px;color:#7e897c}.journal-card{flex:1;min-height:180px;display:flex;flex-direction:column}.journal-list{margin-top:18px;display:flex;flex-direction:column;gap:13px;overflow:auto;max-height:270px}.journal-entry{display:grid;grid-template-columns:20px 1fr;gap:8px;color:#b9c0b0;font-size:11px;line-height:1.55}.journal-entry b{font:10px var(--mono);color:var(--gold)}.journal-empty{font-size:11px;color:#7e897c;line-height:1.6}.die-legend{margin-top:auto;border-top:1px solid var(--line);padding-top:13px;display:flex;align-items:center;gap:9px;font-size:10px;color:#879283}.die-mini{width:28px;height:26px;display:grid;place-items:center;border:1px solid rgba(229,185,103,.35);color:var(--gold);font:8px var(--mono);clip-path:polygon(25% 0,75% 0,100% 50%,75% 100%,25% 100%,0 50%)}.gam